document.addEventListener("DOMContentLoaded", function() {
  console.log("DOMContentLoaded fired");

  // 1) Init Cal with the "optic" namespace (do not call .inline yet)
  Cal("init", "optic", { origin: "https://cal.com" });

  // 2) Capture Webflow fields on submit
  const form = document.getElementById("wf-form-Contact-form");
  if (form) {
    console.log("Form found");
    form.addEventListener("submit", function() {
      console.log("Form submitted");

      // Adjust these IDs to match your Webflow form
      const nameVal       = document.getElementById("name")?.value || "";
      const workEmailVal  = document.getElementById("work-email")?.value || "";
      const companyVal    = document.getElementById("company")?.value || "";
      const regionVal     = document.getElementById("region")?.value || "";

      console.log("Captured values:", { nameVal, workEmailVal, companyVal, regionVal });

      // Save to sessionStorage
      sessionStorage.setItem("prefillName", nameVal);
      sessionStorage.setItem("prefillEmail", workEmailVal);
      sessionStorage.setItem("prefillCompany", companyVal);
      sessionStorage.setItem("prefillRegion", regionVal);
    });
  } else {
    console.log("Form not found");
  }

  // 3) MutationObserver to detect .w-form-done becoming visible
  const successBlock = document.querySelector(".w-form-done");
  if (!successBlock) {
    console.log("No .w-form-done found in DOM");
    return;
  }

  const observer = new MutationObserver(function() {
    const style = window.getComputedStyle(successBlock);
    if (style.display !== "none") {
      console.log("Success block is now visible!");
      observer.disconnect();
      reinitCalWithPrefill();
    }
  });
  observer.observe(successBlock, { attributes: true, attributeFilter: ["style", "class"] });

  // 4) Initialize Cal inline with prefill once .w-form-done is visible
  function reinitCalWithPrefill() {
    const prefillName    = sessionStorage.getItem("prefillName")    || "";
    const prefillEmail   = sessionStorage.getItem("prefillEmail")   || "";
    const prefillCompany = sessionStorage.getItem("prefillCompany") || "";
    const prefillRegion  = sessionStorage.getItem("prefillRegion")  || "";

    console.log("Re-initializing Cal embed with config:", {
      name: prefillName,
      email: prefillEmail,
      company: prefillCompany,
      questions: { "Region": prefillRegion }
    });

    // Show the Cal container
    const bookWrapper = document.querySelector(".embeded-code-book-form");
    if (bookWrapper) {
      bookWrapper.style.display = "block";
    }

    // If "Company" is truly a default field in your Cal form, do this:
    Cal.ns.optic("inline", {
      elementOrSelector: "#my-cal-inline",
      calLink: "forms/92d32956-770a-47e4-b16a-4cb3459eb6fa",
      config: {
        // Default fields: name, email, company
        name:    prefillName,
        email:   prefillEmail,
        company: prefillCompany,
        region: prefillRegion,
        layout: "month_view"
      }
    });

    Cal.ns.optic("ui", {
      hideEventTypeDetails: false,
      layout: "month_view"
    });
  }
});
</script>
